import Image from "next/image";
import Link from "next/link";
import { notFound } from "next/navigation";
import { getDictionary, isValidLocale } from "@/lib/i18n";

export default async function HomePage({
  params,
}: {
  params: Promise<{ lang: string }>;
}) {
  const { lang } = await params;
  if (!isValidLocale(lang)) notFound();

  const dict = getDictionary(lang);
  const nextLocale = lang === "fa" ? "en" : "fa";

  return (
    <section className="mx-auto flex min-h-[85vh] max-w-5xl flex-col justify-center gap-8 px-6 py-16">
      <div className="flex items-center justify-between">
        <span className="text-sm font-medium text-slate-600">
          {dict.meta.jobTitle}
        </span>
        <Link
          href={`/${nextLocale}`}
          className="rounded-lg border border-slate-300 px-3 py-1.5 text-sm font-medium hover:bg-slate-100"
          aria-label={dict.accessibility.switchLanguage}
        >
          {nextLocale.toUpperCase()}
        </Link>
      </div>

      <div className="flex flex-col-reverse items-start gap-8 md:flex-row md:items-center md:justify-between">
        <div className="max-w-2xl space-y-5">
          <h1 className="text-4xl font-bold tracking-tight text-slate-900 sm:text-5xl">
            {dict.hero.heading}
          </h1>
          <p className="text-lg leading-relaxed text-slate-700">
            {dict.hero.subheading}
          </p>
          <div className="flex flex-wrap gap-3 pt-2">
            <Link
              href={`/${lang}/projects`}
              className="rounded-lg bg-slate-900 px-5 py-3 text-sm font-semibold text-white hover:bg-slate-800"
            >
              {dict.hero.primaryCta}
            </Link>
            <Link
              href={`/${lang}/contact`}
              className="rounded-lg border border-slate-300 bg-white px-5 py-3 text-sm font-semibold text-slate-900 hover:bg-slate-50"
            >
              {dict.hero.secondaryCta}
            </Link>
          </div>
        </div>

        <Image
          src="/profile.webp"
          alt={dict.meta.siteName}
          width={220}
          height={220}
          priority
          className="rounded-2xl object-cover shadow-md"
        />
      </div>
    </section>
  );
}